        public ICollection<KeyValuePair<string, bool>> AsCollection()
        {
            List<KeyValuePair<string, bool>> list = new List<KeyValuePair<string, bool>>();
            var productCheckBoxNames = GetProductCheckBoxNames();
            var checkboxAll = productCheckBoxNames[0];
            foreach (string elementName in _filterCollections.Keys)
            {
                if (string.Compare(elementName, checkboxAll) == 0)
                {
                    continue;
                }

                if (_filterCollections[elementName].Visible)
                {
                    list.Add(new KeyValuePair<string, bool>(elementName, _filterCollections[elementName].Checked));
                }
            }

            return list;
        }

        public static string RenderProductFilters(Dictionary<int, bool> permissionDictionary = null)
        {
            var result = new StringBuilder();
            var products = ProductRenderUtility.GetProductHasReport();
            var checkboxLabels = GetProductCheckBoxLabels();
            var checkboxNames = GetProductCheckBoxNames();
            var permissions = permissionDictionary ?? ProductRenderUtility.GetPermissionDictionary();

            var checkboxId = "chk_all";
            var inputFormat = "<input type=\"checkbox\" id=\"{0}\" value=\"true\" name=\"{1}\" checked />";
            var labelFormat = "<label for=\"{0}\">{1}</label>&nbsp;&nbsp;&nbsp;&nbsp;";
            result.Append(string.Format(inputFormat, checkboxId, checkboxId));
            result.Append(string.Format(labelFormat, checkboxId, checkboxLabels[0]));

            var productCheckBoxURLQueryNames = GetProductCheckBoxURLQueryNames();
            foreach (var product in products)
            {
                if (!productCheckBoxURLQueryNames.ContainsKey(product))
                {
                    continue;
                }

                checkboxId = productCheckBoxURLQueryNames[product];
                if (permissions.ContainsKey(product) && permissions[product])
                {
                    result.Append(string.Format(inputFormat, checkboxId, checkboxNames[product]));
                    result.Append(string.Format(labelFormat, checkboxId, checkboxLabels[product]));
                }
            }

            return result.ToString();
        }

        #endregion

        #region Helpers

        private void Render()
        {
            _template.Filter.Clear();

            if (_isShowed)
            {
                FilterElement element = null;
                foreach (string key in _filterCollections.Keys)
                {
                    element = _filterCollections[key];
                    element.Render();
                    _template.Filter.Append(element.Content);
                }
            }
        }

        /// <summary>
        /// Check user permission on all items
        /// </summary>
        private void CheckPermission()
        {
            var permissions = ProductRenderUtility.GetPermissionDictionary();
            var checkBoxIdFromNames = GetProductCheckBoxIdFromNames();
            foreach (string elementName in _filterCollections.Keys)
            {
                var productId = checkBoxIdFromNames[elementName];
                if (!permissions.ContainsKey(productId))
                {
                    continue;
                }

                CheckPermission(permissions[productId], elementName);
            }

            UpdateSportBookItem();

            //Check cross date
            CheckCrossDateConstraint();

            UpdateItemAll();
        }

        /// <summary>
        /// Set nocheck status if user does not have permission 
        /// </summary>
        /// <param name="isAllowedPermission"></param>
        /// <param name="index"></param>
        /// <param name="paramName"></param>
        private void CheckPermission(bool isAllowedPermission, string paramName)
        {
            this._filterCollections[paramName].Visible = isAllowedPermission;
            this._filterCollections[paramName].Checked = GetCheckedParams(paramName);
        }

        /// <summary>
        /// Return true if the param is "on"
        /// </summary>
        /// <param name="paramName"></param>
        /// <returns></returns>
        private bool GetCheckedParams(string paramName)
        {
            string paramValue = _request[FilterElement.PREFIX_ELEMENT + paramName];

            if ((!string.IsNullOrEmpty(paramValue)) && (string.Compare(paramValue.ToLower(), "on") == 0))
            {
                return true;
            }
            else if ((!string.IsNullOrEmpty(paramValue)) && (string.Compare(paramValue.ToLower(), "off") == 0))
            {
                return false;
            }

            return string.IsNullOrEmpty(_request["FilterPostback"]);
        }

        /// <summary>
        /// Check cross date contrain
        /// </summary>
        private void CheckCrossDateConstraint()
        {
            DateTime boundDate = Sunplus.Agent.Model.BL.Definitions.AppSettings.SB_HR_FI_Date;

            //Set constraint of SB, HR, FI if FromDate is before the boundDate
            if (_dateFrom < boundDate)
            {
                var productCheckBoxNames = GetProductCheckBoxNames();
                var sportBook = productCheckBoxNames[ProductIdConstants.Sportsbook];
                var racing = productCheckBoxNames[ProductIdConstants.Racing];
                foreach (string elementName in _filterCollections.Keys)
                {
                    if (elementName == sportBook || elementName == racing)
                    {
                        if (_filterCollections[elementName].Checked)
                        {
                            _filterCollections[sportBook].Checked = true;
                            _filterCollections[racing].Checked = true;

                            break;
                        }
                    }
                }
            }
        }

        /// <summary>
        /// Update sport book item value
        /// </summary>
        private void UpdateSportBookItem()
        {
            bool isNoPermission = true;

            // Check if user have permission on any item
            foreach (string elementName in _filterCollections.Keys)
            {
                if (_filterCollections[elementName].Visible)
                {
                    isNoPermission = false;
                    break;
                }
            }

            var productCheckBoxNames = GetProductCheckBoxNames();
            var checkboxName = productCheckBoxNames[ProductIdConstants.Sportsbook];
            // If user have permission, set sportbook item as request param
            if (isNoPermission)
            {
                _filterCollections[checkboxName].Visible = false;
                _filterCollections[checkboxName].Checked = true;
            }
            else
            {
                _filterCollections[checkboxName].Visible = true;
                _filterCollections[checkboxName].Checked = GetCheckedParams(checkboxName);
            }
        }

        /// <summary>
        /// Update item all
        /// Item all will be showed when one of others was showed
        /// but it will not be showed when only one was showed.
        /// </summary>
        private void UpdateItemAll()
        {
            bool isNoPermission = true, isAll = true;

            // Check if user have permission on any item
            // Check if all item is check
            foreach (string elementName in _filterCollections.Keys)
            {
                if (_filterCollections[elementName].Visible)
                {
                    isNoPermission = false;
                    if (_filterCollections[elementName].Checked == false)
                    {
                        isAll = false;
                    }
                }
            }

            var productCheckBoxNames = GetProductCheckBoxNames();
            var checkboxName = productCheckBoxNames[0];
            // If user have permission on any item
            if (isNoPermission)
            {
                _filterCollections[checkboxName].Visible = false;
            }
            else
            {
                _filterCollections[checkboxName].Visible = true;
                _filterCollections[checkboxName].Checked = isAll;
            }
        }

